-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann ich als Azubi vor ein Arbeitsgericht ziehen?', 2, '[{"text": "Ja", "correct": true, "because": "ArbGG gilt für Arbeitnehmer"}, {"text": "Nein", "correct": false, "because": "Azubis eingeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Streit mit meinem Chef immer vor ein Arbeitsgericht?', 2, '[{"text": "Nein", "correct": true, "because": "Erst interne Klärung möglich"}, {"text": "Ja", "correct": false, "because": "Nur bei Eskalation"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Arbeitsgerichtsgesetz für Kündigungen relevant?', 2, '[{"text": "Ja", "correct": true, "because": "Regelt Arbeitsstreitigkeiten"}, {"text": "Nein", "correct": false, "because": "Kündigungsschutz inklusive"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich wegen meines Urlaubs vor ein Arbeitsgericht ziehen?', 2, '[{"text": "Ja", "correct": true, "because": "Arbeitsstreit möglich"}, {"text": "Nein", "correct": false, "because": "Urlaub ist Streitgegenstand"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Regelt das ArbGG meine Vergütung?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Verfahren, nicht Inhalte"}, {"text": "Ja", "correct": false, "because": "Tarif- oder Vertragsrecht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Betriebsrat mich vor einem Arbeitsgericht vertreten?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Anwalt oder Gewerkschaft"}, {"text": "Ja", "correct": false, "because": "Vertretung eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Arbeitsgerichtsgesetz für alle Betriebe bindend?', 2, '[{"text": "Ja", "correct": true, "because": "Gilt für Arbeitsstreitigkeiten"}, {"text": "Nein", "correct": false, "because": "Allgemein anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte das ArbGG meine Arbeitszeit betreffen?', 2, '[{"text": "Nein", "correct": true, "because": "ArbZG regelt Arbeitszeit"}, {"text": "Ja", "correct": false, "because": "Nur Streitverfahren"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was regelt das Arbeitsgerichtsgesetz hauptsächlich?', 2, '[{"text": "Verfahren bei Arbeitsstreitigkeiten", "correct": true, "because": "Kern des ArbGG"}, {"text": "Arbeitszeiten", "correct": false, "because": "ArbZG"}, {"text": "Vergütung", "correct": false, "because": "Tarifrecht"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin kündigt mich. Was sagt das ArbGG?', 3, '[{"text": "Ich kann Klage erheben", "correct": true, "because": "Verfahren geregelt"}, {"text": "Kündigung ist automatisch ungültig", "correct": false, "because": "Gericht entscheidet"}, {"text": "Nichts geht", "correct": false, "because": "Klagerecht gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer kann mich vor einem Arbeitsgericht vertreten?', 2, '[{"text": "Anwalt", "correct": true, "because": "ArbGG erlaubt Anwälte"}, {"text": "Chef", "correct": false, "because": "Gegenseite"}, {"text": "Freund", "correct": false, "because": "Keine Befugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt, wann ich das Arbeitsgericht anrufen kann. Was sage ich?', 3, '[{"text": "Bei Streit über Kündigung", "correct": true, "because": "Typischer Fall"}, {"text": "Für Urlaubsplanung", "correct": false, "because": "Betriebssache"}, {"text": "Für Gehaltserhöhung", "correct": false, "because": "Tarifverhandlung"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Streitigkeiten regelt das ArbGG?', 4, '[{"text": "Kündigungen", "correct": true, "because": "Hauptfall"}, {"text": "Arbeitsverträge", "correct": true, "because": "Vertragsstreit"}, {"text": "Lohnforderungen", "correct": true, "because": "Gängig"}, {"text": "Steuerstreit", "correct": false, "because": "Finanzgericht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was kann ich vor einem Arbeitsgericht klären?', 3, '[{"text": "Ungerechte Kündigung", "correct": true, "because": "Kündigungsschutz"}, {"text": "Nicht bezahlte Überstunden", "correct": true, "because": "Lohnstreit"}, {"text": "Betriebsratsrechte", "correct": true, "because": "Mitbestimmung"}, {"text": "Urlaubsorte", "correct": false, "because": "Kein Arbeitsstreit"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir haben Streit mit dem Betrieb. Was regelt das ArbGG?', 3, '[{"text": "Zuständigkeit Arbeitsgericht", "correct": true, "because": "Gerichtsstand"}, {"text": "Verfahrensregeln", "correct": true, "because": "Prozessrecht"}, {"text": "Fristen für Klage", "correct": true, "because": "Zeitliche Grenzen"}, {"text": "Arbeitszeiten", "correct": false, "because": "ArbZG"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte gibt mir das ArbGG?', 4, '[{"text": "Klagerecht bei Streit", "correct": true, "because": "Zugang zu Gericht"}, {"text": "Anhörung vor Kündigung", "correct": true, "because": "Verfahrensschutz"}, {"text": "Schnelle Verfahren", "correct": true, "because": "ArbGG-Ziel"}, {"text": "Feste Vergütung", "correct": false, "because": "Tarifsache"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das ArbGG regelt Arbeitsstreitigkeiten. b) Es legt meine Arbeitszeit fest.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Streit ja, Arbeitszeit nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ich kann wegen Kündigung klagen. b) Das ArbGG gilt nur für große Betriebe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klage ja, Größe egal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das ArbGG erlaubt schnelle Verfahren. b) Es regelt meinen Urlaub.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verfahren ja, Urlaub nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das ArbGG gibt mir Klagerecht. b) Es zwingt den Betrieb, mich anzuhören.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klage ja, Anhörung BetrVG"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

